    },
    {
      src: "/assets/stock-images/association-roles/association-roles-partners.webp",
      alt: "Crays partners planning standards and execution"
    },
    {
      src: "/assets/stock-images/association-roles/association-roles-operators.webp",
      alt: "Crays operators guiding local hospitality experiences"
    },
    {
      src: "/assets/stock-images/association-roles/association-roles-investors.webp",
      alt: "Crays investor travelling between project and capital conversations"
    }
  ];

  function enhanceAssociationRoleCards() {
    document.querySelectorAll(".crays-articles-section--roles .crays-articles-role-grid .crays-articles-card").forEach(function (card, index) {
      var roleImage = roleImages[index];
      if (!roleImage) return;
      card.setAttribute("data-role-number", String(index + 1).padStart(2, "0"));
      if (card.querySelector(".crays-articles-role-media")) return;

      var figure = document.createElement("figure");
      figure.className = "crays-articles-role-media";

      var image = document.createElement("img");
      image.src = roleImage.src;
      image.alt = roleImage.alt;
      image.loading = "lazy";

      figure.appendChild(image);
      card.insertBefore(figure, card.firstChild);
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", enhanceAssociationRoleCards, { once: true });
  } else {
    enhanceAssociationRoleCards();
  }
})();

