(function () {
  var luxuryFlowImages = {
    social: "/assets/stock-images/association-luxury-flow/association-luxury-social-selfie.jpeg",
    yacht: "/assets/stock-images/association-luxury-flow/association-luxury-yacht-group.jpeg",
    cityPool: "/assets/stock-images/association-luxury-flow/association-luxury-city-pool.jpeg",
    palm: "/assets/stock-images/association-luxury-flow/association-luxury-palm-sunset.jpeg",
    lounge: "/assets/stock-images/association-luxury-flow/association-luxury-fireplace-lounge.jpeg",
    suite: "/assets/stock-images/association-luxury-flow/association-luxury-villa-suite.jpeg"
  };

  function luxuryImage(src, alt) {
    var img = document.createElement("img");
    img.src = src;
    img.alt = alt;
    img.loading = "lazy";
    img.decoding = "async";
    return img;
  }

  function luxuryFigure(className, src, alt, label) {
    var figure = document.createElement("figure");
    figure.className = className;
    figure.appendChild(luxuryImage(src, alt));
    if (label) {
      var caption = document.createElement("figcaption");
      var span = document.createElement("span");
      span.textContent = label;
      caption.appendChild(span);
      figure.appendChild(caption);
    }
    return figure;
  }

  function runFinalLuxuryPass() {
    var main = document.querySelector("main.crays-articles-final");
    if (!main) return;

    var structureTitle = main.querySelector(":scope > .crays-articles-section--structure-intro .crays-articles-section-title");
    if (structureTitle && structureTitle.textContent.trim() === "Formal governance. DAO Voting Specialist execution." && structureTitle.dataset.finalLuxurySplit !== "true") {
      structureTitle.textContent = "";
      ["Formal", "governance.", "DAO", "Voting", "Specialist", "execution."].forEach(function (part, index) {
        if (index) structureTitle.appendChild(document.createTextNode(" "));
        var span = document.createElement("span");
        span.textContent = part;
        structureTitle.appendChild(span);
      });
      structureTitle.dataset.finalLuxurySplit = "true";
    }

    var membershipVisual = main.querySelector(":scope > .crays-articles-section--members .crays-membership-visual");
    if (membershipVisual && !membershipVisual.classList.contains("crays-membership-visual--collage")) {
      membershipVisual.classList.add("crays-membership-visual--collage");
      membershipVisual.appendChild(luxuryImage(luxuryFlowImages.social, "Crays members sharing a premium lifestyle moment"));
      membershipVisual.appendChild(luxuryImage(luxuryFlowImages.cityPool, "Luxury city pool connected to member access and global mobility"));
    }

    var partner = main.querySelector(":scope > .crays-articles-section--partner");
    if (partner && !partner.id) partner.id = "partner";
    var partnerShell = partner && partner.querySelector(":scope > .crays-articles-shell");
    var partnerIntro = partnerShell && partnerShell.querySelector(":scope > .crays-articles-partner-intro");
    var partnerGrid = partnerShell && partnerShell.querySelector(":scope > .crays-articles-card-grid--six");
    if (partnerShell && partnerIntro && partnerGrid && !partnerShell.classList.contains("crays-partner-luxury-layout")) {
      partnerShell.classList.add("crays-partner-luxury-layout");
      partnerIntro.classList.add("crays-partner-luxury-intro");
      partnerGrid.classList.add("crays-partner-luxury-grid");

      var cardImages = [
        [luxuryFlowImages.lounge, "Premium hospitality lounge for hotels clubs and spaces"],
        [luxuryFlowImages.cityPool, "City pool and skyline for real estate owners and developers"],
        [luxuryFlowImages.suite, "Luxury suite and digital work setting for AI Web5 payments and venue infrastructure"],
        [luxuryFlowImages.palm, "Palm sunset venue for finance and real-world asset participation"],
        [luxuryFlowImages.social, "Lifestyle creators and brands building culture around Crays"],
        [luxuryFlowImages.yacht, "Local leaders and operators connecting the community"]
      ];
      Array.prototype.forEach.call(partnerGrid.querySelectorAll(":scope > .crays-articles-card"), function (card, index) {
        card.classList.add("crays-partner-card");
        card.setAttribute("data-partner-number", String(index + 1).padStart(2, "0"));
        if (!card.querySelector(".crays-partner-card-media")) {
          card.insertBefore(luxuryFigure("crays-partner-card-media", cardImages[index][0], cardImages[index][1], ""), card.firstElementChild);
        }
      });
    }

    if (partner && window.location.hash === "#partner") {
      partner.scrollIntoView({ block: "start" });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", runFinalLuxuryPass);
  } else {
    runFinalLuxuryPass();
  }
})();

