(function () {
  function normalize(value) {
    return (value || "").replace(/\s+/g, " ").trim();
  }

  function replaceExactText(selector, oldText, newText) {
    Array.prototype.forEach.call(document.querySelectorAll(selector), function (element) {
      if (normalize(element.textContent) === oldText) {
        element.textContent = newText;
      }
    });
  }

  function ensureAssociationFooterClose() {
    var footer = document.querySelector("footer.crays-footer-rebuild");
    if (!footer) return;

    var upperCta = document.querySelector("main.crays-articles-final > .crays-articles-cta");
    var cta = document.querySelector(".crays-association-mid-cta");
    if (!cta) {
      cta = document.createElement("section");
      cta.className = "crays-association-mid-cta";
      cta.setAttribute("aria-labelledby", "crays-association-mid-cta-title");
      footer.parentNode.insertBefore(cta, footer);
    }

    cta.innerHTML = [
      '<div class="crays-association-mid-cta__inner">',
      '<h2 class="crays-association-mid-cta__title" id="crays-association-mid-cta-title">',
      '<span>New projects and partners</span>',
      '<span>Join us!</span><br>',
      '<span>And add</span><br>',
      '<span>real value.</span>',
      '</h2>',
      '<div class="crays-association-mid-cta__content">',
      '<p class="crays-association-mid-cta__copy">Join as an operator, venue partner, real estate owner, technology builder, lifestyle brand, finance partner or local community leader when you can help build responsibly.</p>',
      '<a class="crays-association-mid-cta__button" href="/ca/join-us/#project-intake">Start a project conversation</a>',
      '</div>',
      '</div>'
    ].join("");

    if (upperCta) upperCta.remove();
  }

  function runAssociationFinalRequestPass() {
    Array.prototype.forEach.call(document.querySelectorAll(".crays-articles-hero-panel > .crays-articles-kicker"), function (element) {
      if (normalize(element.textContent) === "What this gives you") {
        element.remove();
      }
    });

    replaceExactText(
      ".crays-articles-trust-band .crays-articles-section-title, .crays-articles-section-title",
      "The Articles make Crays reliable.",
      "Your governance rules make Crays trustworthy"
    );

    replaceExactText(
      ".crays-articles-trust-band .crays-articles-section-copy, .crays-articles-section-copy",
      "They make clear who can join, who can vote, how projects are approved, how funds are used, how disputes are handled and where commercial upside belongs. That clarity is what lets Crays connect community, hospitality, technology, finance and real estate without becoming vague.",
      "Crays governance is embedded in code. Because code is law. In code we trust. The rules make clear how you join, how you vote, how projects are approved, how association funds are allocated, how disputes are resolved and where commercial upside belongs."
    );

    ensureAssociationFooterClose();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", runAssociationFinalRequestPass);
  } else {
    runAssociationFinalRequestPass();
  }
})();

